135: 
136:         protected override async Task ExecuteAsync(CancellationToken stoppingToken)
137:         {
138:             while (!stoppingToken.IsCancellationRequested)
139:             {
140:                 _logger.LogInformation("Worker running at: {time}", DateTimeOffset.Now);
141:                 // In a real app, this would dequeue a message
142:                 await SendWelcomeEmail("new.user@example.com");
